<template>
  <section class="dashboard-page" dir="rtl">
    <header class="dashboard-header"><div><h1>داشبورد مدیریت</h1><p>نمای عملیاتی کسب‌وکار در بازه انتخاب‌شده</p></div><button class="primary" :disabled="loading" @click="load">{{ loading ? 'در حال به‌روزرسانی…' : '↻ به‌روزرسانی' }}</button></header>
    <form class="filters" @submit.prevent="applyRange"><JalaliDatePicker :model-value="filters.start_date" model-format="jYYYY/jMM/jDD" :clearable="false" placeholder="از تاریخ" @update:model-value="setDate('start_date',$event)"/><JalaliDatePicker :model-value="filters.end_date" model-format="jYYYY/jMM/jDD" :clearable="false" placeholder="تا تاریخ" @update:model-value="setDate('end_date',$event)"/><button class="secondary" :disabled="loading">اعمال بازه</button><button type="button" class="secondary" :disabled="loading" @click="resetFilters">بازنشانی</button><div class="quick"><button v-for="item in quickFilters" :key="item.value" type="button" :disabled="loading" @click="setQuick(item.value)">{{item.label}}</button></div><span v-if="dashboard.period" class="period">{{ dashboard.period.label }}</span></form>
    <div v-if="loading && !loaded" class="state">در حال دریافت داده‌های داشبورد…</div><div v-else-if="error" class="state error"><strong>دریافت اطلاعات ناموفق بود</strong><span>{{ error }}</span><button class="primary" @click="load">تلاش مجدد</button></div>
    <template v-else-if="loaded"><div class="cards"><article><span>کل سفارش‌ها</span><strong>{{num(dashboard.summary.orders.total)}}</strong><small>{{num(dashboard.summary.orders.delivered)}} تحویل‌شده</small></article><article><span>در جریان</span><strong>{{num(dashboard.summary.orders.pending)}}</strong><small>{{num(dashboard.summary.orders.cancelled)}} لغوشده</small></article><article><span>مشتریان جدید</span><strong>{{num(dashboard.summary.customers)}}</strong><small>ثبت‌شده در بازه</small></article><article><span>هشدار موجودی</span><strong>{{num(dashboard.summary.low_stock)}}</strong><small>کالای نزدیک اتمام</small></article><template v-if="financial"><article class="financial"><span>فروش تکمیل‌شده</span><strong>{{money(financial.sales)}}</strong><small>محرمانه</small></article><article class="financial"><span>هزینه‌ها</span><strong>{{money(financial.expenses)}}</strong><small>محرمانه</small></article><article class="financial"><span>خالص دوره</span><strong>{{money(financial.net)}}</strong><small>فروش منهای هزینه</small></article></template></div>
      <div class="grid"><section><h2>روند سفارش‌ها</h2><div v-if="dashboard.order_chart.length" class="bar-chart"><div v-for="row in dashboard.order_chart" :key="row.date" class="bar"><i :style="{height:bar(row.orders)+'%'}"></i><strong>{{num(row.orders)}}</strong><small>{{row.date.slice(5)}}</small></div></div><p v-else class="empty">سفارشی در این بازه ثبت نشده است.</p></section><section><h2>وضعیت سفارش‌ها</h2><div v-for="row in dashboard.order_status" :key="row.status" class="progress"><span>{{status(row.status)}}</span><b>{{num(row.count)}}</b><i :style="{width:percent(row.count)+'%'}"></i></div><p v-if="!dashboard.order_status.length" class="empty">داده‌ای وجود ندارد.</p></section><section><h2>موجودی کم</h2><div v-for="item in dashboard.low_stock_products" :key="item.id" class="row"><span>{{item.name}}</span><strong>{{num(item.inventory)}} عدد</strong></div><p v-if="!dashboard.low_stock_products.length" class="empty">هشدار موجودی وجود ندارد.</p></section><section><h2>فعالیت‌های اخیر</h2><div v-for="activity in dashboard.recent_activity" :key="activity.id" class="row"><span><strong>{{activity.title}}</strong><small>{{activity.customer}} · {{date(activity.created)}}</small></span><b>{{status(activity.status)}}</b></div><p v-if="!dashboard.recent_activity.length" class="empty">فعالیتی در این بازه نیست.</p></section><section v-if="financial" class="wide"><h2>هزینه بر اساس دسته</h2><div v-for="category in financial.expense_categories" :key="category.category__name" class="row"><span>{{category.category__name}}</span><strong>{{money(category.total)}} <small>{{num(category.count)}} مورد</small></strong></div><p v-if="!financial.expense_categories.length" class="empty">هزینه‌ای ثبت نشده است.</p></section></div></template><CostToastHost/></section>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import DashboardApi from '@/api/dashboard.js'
import JalaliDatePicker from '@/components/cost/JalaliDatePicker.vue'
import CostToastHost from '@/components/cost/CostToastHost.vue'
import { useCostToast } from '@/composables/useCostToast'
import { jalaliToday, jalaliToIso, normalizeJalali } from '@/utils/jalaliDate'
const storedFilters=JSON.parse(sessionStorage.getItem('dashboard-jalali-range')||'null'); const dashboard=reactive({summary:{orders:{}},order_chart:[],order_status:[],low_stock_products:[],recent_activity:[]}), filters=reactive(storedFilters||defaultRange()), loaded=ref(false),loading=ref(false),error=ref(''),toast=useCostToast(),quickFilters=[{value:'today',label:'امروز'},{value:'week',label:'هفته جاری'},{value:'month',label:'ماه جاری'},{value:'year',label:'سال جاری'}]
const financial=computed(()=>dashboard.financial)
const num=value=>Number(value||0).toLocaleString('fa-IR'); const money=value=>`${num(value)} تومان`; const status=value=>({pending:'در انتظار',prep:'در حال آماده‌سازی',send:'در حال ارسال',deliver:'تحویل‌شده',cancel:'لغوشده'})[value]||value; const date=value=>value?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Tehran'}).format(new Date(value)):'—'; const bar=value=>{const max=Math.max(...dashboard.order_chart.map(row=>row.orders),1);return Math.max(6,Number(value||0)/max*100)}; const percent=value=>{const total=dashboard.summary.orders.total||0;return total?Math.max(4,value/total*100):0}
function defaultRange(){const today=jalaliToday();return {start_date:`${today.slice(0,4)}/${today.slice(5,7)}/01`,end_date:today}}
function persist(){sessionStorage.setItem('dashboard-jalali-range',JSON.stringify({...filters}))}
function setDate(key,value){filters[key]=normalizeJalali(value)||'';persist()}
function requestParams(){const start=jalaliToIso(filters.start_date),end=jalaliToIso(filters.end_date);if(!start||!end)throw new Error('ابتدا تاریخ شروع و پایان معتبر انتخاب کنید.');if(start>end)throw new Error('تاریخ پایان باید بعد از تاریخ شروع باشد.');return {start_date:start,end_date:end}}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const {data}=await DashboardApi.dashboard(requestParams());if(!data.success)throw new Error(data.message);Object.assign(dashboard,data.data);loaded.value=true;toast.success(data.message)}catch(cause){error.value=cause.response?.data?.message||cause.message||'ارتباط با سرور برقرار نشد.'}finally{loading.value=false}}
function applyRange(){persist();load()}
function resetFilters(){Object.assign(filters,defaultRange());persist();load()}
function setQuick(value){const today=jalaliToday();if(value==='today')Object.assign(filters,{start_date:today,end_date:today});else if(value==='week')Object.assign(filters,{start_date:jalaliToday(-((new Date().getDay()+1)%7)),end_date:today});else if(value==='year')Object.assign(filters,{start_date:`${today.slice(0,4)}/01/01`,end_date:today});else Object.assign(filters,defaultRange());persist();load()}
onMounted(load)
</script>
<style scoped>
.dashboard-page{display:grid;gap:1rem}.dashboard-header,.filters{display:flex;align-items:center;justify-content:space-between;gap:.8rem;flex-wrap:wrap}.dashboard-header h1{margin:0;color:var(--text);font-size:1.5rem}.dashboard-header p,.period,.empty,.row small{color:var(--muted);font-size:.85rem}.primary,.secondary,.quick button{min-height:40px;border-radius:8px;padding:.55rem .9rem;border:1px solid var(--primary);font:inherit;cursor:pointer}.primary{background:var(--primary);color:#fff}.secondary,.quick button{background:var(--surface);color:var(--text);border-color:var(--border-strong)}.primary:disabled,.secondary:disabled{opacity:.6;cursor:not-allowed}.filters{justify-content:flex-start;padding:1rem;background:var(--surface);border:1px solid var(--border);border-radius:14px}.quick{display:flex;flex-wrap:wrap;gap:.4rem}.quick button{min-height:34px;padding:.35rem .6rem;font-size:.78rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:.8rem}.cards article,.grid section{background:var(--surface);border:1px solid var(--border);box-shadow:var(--shadow);border-radius:14px;padding:1rem}.cards article{display:grid;gap:.45rem;border-top:3px solid var(--primary)}.cards .financial{border-top-color:#8b5cf6}.cards span{color:var(--muted);font-size:.83rem}.cards strong{color:var(--text);font-size:1.35rem}.cards small{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.grid .wide{grid-column:1/-1}.grid h2{font-size:1rem;margin:0 0 .9rem;color:var(--text)}.bar-chart{height:185px;display:flex;align-items:end;gap:.5rem;padding-top:1rem;overflow-x:auto}.bar{min-width:38px;height:100%;display:grid;grid-template-rows:1fr auto auto;align-items:end;justify-items:center;gap:.25rem;font-size:.72rem;color:var(--muted)}.bar i{width:100%;border-radius:5px 5px 0 0;background:var(--primary);min-height:3px}.bar strong{color:var(--text)}.progress{position:relative;display:grid;grid-template-columns:1fr auto;gap:.35rem;padding:.55rem 0;border-bottom:1px solid var(--border);font-size:.85rem}.progress i{grid-column:1/-1;height:6px;border-radius:99px;background:var(--primary)}.row{display:flex;justify-content:space-between;gap:.75rem;padding:.65rem 0;border-bottom:1px solid var(--border);font-size:.87rem}.row span{display:grid;gap:.2rem}.row b{font-size:.78rem;color:var(--primary);white-space:nowrap}.state{min-height:260px;display:grid;place-content:center;justify-items:center;gap:.8rem;background:var(--surface);border:1px solid var(--border);border-radius:14px;color:var(--muted)}.state.error{color:var(--danger)}@media(max-width:720px){.grid{grid-template-columns:1fr}.dashboard-header{align-items:flex-start}.filters>*{width:100%}.filters .period{width:auto}.grid .wide{grid-column:auto}}
</style>
